{
  "name": "opencode-ghost",
  "version": "1.3.16",
  "description": "OpenCode ghost text autosuggest: suggests your next message as dimmed inline ghost text in the empty TUI composer, accepted with Tab or Right arrow.",
  "type": "module",
  "license": "MIT",
  "author": "Ozan Dogrultan",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ozandogrultan/opencode-ghost.git"
  },
  "homepage": "https://github.com/ozandogrultan/opencode-ghost#readme",
  "bugs": {
    "url": "https://github.com/ozandogrultan/opencode-ghost/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "ghost-text",
    "autosuggest",
    "prompt",
    "suggestion",
    "next-prompt",
    "opencode-tui"
  ],
  "exports": {
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "CHANGELOG.md",
    "LICENSE",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "packageManager": "bun@1.4.2",
  "engines": {
    "opencode": ">=2.2.3"
  },
  "scripts": {
    "prepare": "husky",
    "test": "bun test && bash tests/changelog.sh",
    "test:unit": "bun test",
    "test:changelog": "bash tests/changelog.sh",
    "typecheck": "tsc --noEmit",
    "lint:sh": "for script in install.sh tests/*.sh scripts/*.sh; do bash -n \"$script\" || exit; done && node --check scripts/install.mjs",
    "prepublishOnly": "bun run test && bun run typecheck"
  },
  "dependencies": {
    "@opentui/core": "^0.9.7",
    "@opentui/solid": "^0.9.7"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.4.0",
    "solid-js": "*"
  },
  "devDependencies": {
    "@commitlint/cli": "^21.2.2",
    "@commitlint/config-conventional": "^21.2.2",
    "@opencode/client": "2.3.2",
    "@opencode/plugin": "2.3.2",
    "@types/bun": "^1.4.3",
    "@types/node": "26.6.6",
    "husky": "^9.1.7",
    "solid-js": "1.9.12",
    "typescript": "7.0.2"
  }
}
